contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // amount to send to c.go; this function is payable so caller can fund this contract.
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        // ensure this contract has funds to send
        require(address(this).balance >= amount);

        // observe owner and c balance before
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint beforeCBalance = address(c).balance;

        // perform the state-changing call to c.go sending `amount`
        bool reverted;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe after values
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;
        uint afterCBalance = address(c).balance;

        // General invariant: owner never changes and c holds no Ether after the call
        assert(ownerAfter == ownerBefore && afterCBalance == 0);
    }

    receive() external payable {}
}

